#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static long long findPoisonedDuration(const int *timeSeries, int n, int duration) {
    if (duration == 0) return 0LL;
    long long total = duration;
    for (int i = 0; i + 1 < n; ++i) {
        long long gap = (long long)timeSeries[i + 1] - timeSeries[i];
        total += gap < duration ? gap : duration;
    }
    return total;
}

