static vector<int> parseTimeSeries(const string& line) {
    size_t open = line.find('[', 1);
    size_t close = line.find(']', open);
    vector<int> result;
    string inner = line.substr(open + 1, close - open - 1);
    if (inner.empty()) return result;
    string token;
    stringstream ss(inner);
    while (getline(ss, token, ',')) result.push_back(stoi(token));
    return result;
