public class Main {
    static int[] parseTimeSeries(String line) {
        int open = line.indexOf('[', 1);
        int close = line.indexOf(']', open);
        String inner = line.substring(open + 1, close).trim();
        if (inner.isEmpty()) return new int[0];
        String[] parts = inner.split("\\s*,\\s*");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i].trim());
        }
        return result;
    }

    static int parseDuration(String line) {
        int open = line.indexOf('[', 1);
        int close = line.indexOf(']', open);
        String rest = line.substring(close + 1).trim();
        if (rest.startsWith(",")) rest = rest.substring(1).trim();
        if (rest.endsWith("]")) rest = rest.substring(0, rest.length() - 1).trim();
        return Integer.parseInt(rest);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int[] timeSeries = parseTimeSeries(line);
        int duration = parseDuration(line);
        System.out.println(new Solution().findPoisonedDuration(timeSeries, duration));
    }
}

